    if event_type not in self._event_listeners:
        self._event_listeners[event_type] = []
    self._event_listeners[event_type].append(callback)

def notify(self, event_type, details):
    if not self.can_be_registered(event_type):
        raise ValueError(f"Event type {event_type} can not be registered.")

    callbacks = self._event_listeners[event_type]
    total_listeners = len(callbacks)
    successful_calls = 0
    unsuccessful_calls = 0

    async def call_callback(callback):
        nonlocal successful_calls, unsuccessful_calls
        try:
            await callback(details=details)
            successful_calls += 1
        except Exception:
            unsuccessful_calls += 1

    tasks = [call_callback(callback) for callback in callbacks]
    result = asyncio.run(asyncio.gather(*tasks))

    Result = namedtuple("Result", ["total_listeners", "successful_calls", "unsuccessful_calls"])
    return Result(total_listeners, successful_calls, unsuccessful_calls)

