  appends the result to the list *dest*. If *dest* is #None, it will fall
  back to `sys.path`.

  If *imports* is specified, it must be a list. `import` statements will not
  executed but instead appended to that list in tuples of
  (*filename*, *line*, *stmt*).

  Returns a tuple of (*dest*, *imports*).
  """
    if dest is None:
        dest = sys.path
    if imports is None:
        imports = []

    with open(filename, 'r') as f:
        source = f.read()
    tree = ast.parse(source, filename)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.append((filename, node.lineno, alias.name))
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                if alias.name.startswith('.'):
                    continue
                imports.append((filename, node.lineno, f'{node.module}.{alias.name}'))
        elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Str):
            dest.append(os.path.join(sitedir, node.value.s))

    return dest, imports

